mapper.select:
SELECT tmp.deviceCode AS deviceCode, tmp.deviceName AS deviceName, tmp.deviceType AS deviceType, tmp.longitude AS longitude, tmp.latitude AS latitude, tmp.distance AS distance from (
select de.device_code deviceCode, (case when length(IFNULL(ten.device_name, '')) = 0 then de.device_name else ten.device_name end ) deviceName, de.longitude,de.latitude, '1' AS deviceType, ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance from vm_order_devices ord left join vm_device_info_t de on ord.device_code = de.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = ord.device_code and ten.tenant_id = ord.tenant_id and ten.delete_flag='0' and ten.industry_code = ord.industry_code where ord.delete_flag = '0' and de.delete_flag = '0' and ord.ord_status in (0, 1, 2) and de.device_status = 0
and ord.tenant_id = #{tenantId}
and ord.industry_code = #{industryCode}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 <= #{distance} ${dataScope}
SELECT ord.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then de.device_name else ten.device_name end ) AS deviceName, de.longitude, de.latitude, '2' AS deviceType, ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance FROM vm_order_sensor_devices ord LEFT JOIN vm_order_customer oc on ord.order_code = oc.order_code LEFT JOIN vm_iot_device_t de on de.device_code = ord.device_code and de.category_code = 2 LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = ord.device_code and ten.tenant_id = ord.tenant_id and ten.delete_flag='0' and ten.industry_code = ord.industry_code where ord.delete_flag = '0' and de.delete_flag = '0' and ord.category_code = 2 and ord.ord_status in (0, 1, 2)
and ord.tenant_id = #{tenantId}
and ord.industry_code = #{industryCode}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 <= #{distance} ${dataScope}
select de.device_code deviceCode, (case when length(IFNULL(ten.device_name, '')) = 0 then de.device_name else ten.device_name end ) deviceName, de.longitude,de.latitude, '1' AS deviceType, ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance from vm_order_devices ord left join vm_device_info_t de on ord.device_code = de.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = ord.device_code and ten.tenant_id = ord.tenant_id and ten.delete_flag='0' and ten.industry_code = ord.industry_code where ord.delete_flag = '0' and de.delete_flag = '0' and ord.ord_status in (0, 1, 2) and de.device_status = 0
and ord.tenant_id = #{tenantId}
and ord.industry_code = #{industryCode}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 <= #{distance} ${dataScope} UNION ALL SELECT ord.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then de.device_name else ten.device_name end ) AS deviceName, de.longitude, de.latitude, '2' AS deviceType, ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 AS distance FROM vm_order_sensor_devices ord LEFT JOIN vm_order_customer oc on ord.order_code = oc.order_code LEFT JOIN vm_iot_device_t de on de.device_code = ord.device_code and de.category_code = 2 LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = ord.device_code and ten.tenant_id = ord.tenant_id and ten.delete_flag='0' and ten.industry_code = ord.industry_code where ord.delete_flag = '0' and de.delete_flag = '0' and ord.category_code = 2 and ord.ord_status in (0, 1, 2)
and ord.tenant_id = #{tenantId}
and ord.industry_code = #{industryCode}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(de.longitude,de.latitude))*111195 <= #{distance} ${dataScope}
) tmp ORDER BY distance ASC

SELECT DISTINCT t5.device_code, t5.latitude, t5.longitude, ( case when length(IFNULL(ten.device_name, '')) = 0 then t1.device_name else ten.device_name end ) device_name, t5.device_status deviceStatus, t5.category_code deviceType, IF(IFNULL(t6.user_device_coll_id,0) = 0, '0', '1') isMonitor FROM vm_order_devices t1 LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = t1.device_code AND ten.industry_code = t1.industry_code AND ten.tenant_id = t1.tenant_id AND ten.delete_flag='0'
LEFT JOIN vm_algorithm_config t2 ON t1.order_code = t2.order_code AND t2.delete_flag = 0 AND t2.device_code = t1.device_code
LEFT JOIN vm_device_labels_rel t3 ON t1.device_code = t3.device_code
LEFT JOIN vm_organ_device_rel_t t4 ON t1.device_code = t4.device_code AND t4.delete_flag = '0'
LEFT JOIN vm_device_info_t t5 ON t1.device_code = t5.device_code LEFT JOIN vm_user_device_collection_t t6 ON t6.coll_obj_code = t1.device_code AND t6.coll_obj_type = '5' AND t6.user_id = #{userId} WHERE t1.delete_flag = 0 AND t1.ord_status IN (0,1,2) AND t5.delete_flag = '0'
and t3.label_id IN
#{item}
and t2.algorithm_code IN
#{item}
and t5.category_code IN
#{item}
and t4.dept_id IN
#{item}
${dataScope}

SELECT DISTINCT t.dept_id, t.device_code, t2.device_status AS isOnline FROM vm_organ_device_rel_t t LEFT JOIN vm_device_info_t t2 ON t.device_code = t2.device_code LEFT JOIN vm_order_devices t1 ON t.device_code = t1.device_code AND t1.tenant_id = t.tenant_id AND t1.industry_code = t.industry_code LEFT JOIN vm_channel_info_t ci ON ci.device_code = t1.device_code WHERE t.delete_flag = 0 AND t.device_type = 4 AND t2.delete_flag = 0 AND t1.delete_flag = '0' AND ci.delete_flag = '0' AND t1.ord_status IN (0,1,2) AND t.dept_id IN
#{item}
${dataScope}

