SELECT DISTINCT t5.device_code, t5.latitude, t5.longitude, ( case when length(IFNULL(ten.device_name, '')) = 0 then t1.device_name else ten.device_name end ) device_name, t5.device_status deviceStatus, t5.category_code deviceType FROM vm_order_devices t1 LEFT JOIN vm_tenant_device_channel_rel_t ten on ten.device_code = t1.device_code AND ten.industry_code = t1.industry_code AND ten.tenant_id = t1.tenant_id AND ten.delete_flag='0' LEFT JOIN vm_device_info_t t5 ON t1.device_code = t5.device_code WHERE t1.delete_flag = 0 AND t1.ord_status IN (0,1,2) AND t5.delete_flag = '0' AND t1.device_code in
#{deviceCode}
${dataScope}
